SCORES = {'E0': .08, 'E1': .85, 'E2': .55, 'E3': .45}
def write_repository(output: Path | None = None) -> Path:
    output = output or Path(__file__).with_name('onet_task_repository.csv')
    fields = ['onet_soc_code','occupation','onet_task_id','onet_rank','task_type','importance','task','exposure_rating','automation_potential','judgment_intensity','exposure_category','exposure_rationale','family_label']
    with output.open('w', newline='', encoding='utf-8') as file:
        writer = csv.DictWriter(file, fieldnames=fields); writer.writeheader()
        for task_id,soc,occ,rank,task,rating,judgment,category,rationale,families in RAW_TASKS:
            writer.writerow({'onet_soc_code':soc,'occupation':occ,'onet_task_id':task_id,'onet_rank':rank,'task_type':'Core' if families.split('|')[0] == task_id.split('-')[0] else 'Supporting','importance':round(1-(rank-1)*.08,2),'task':task,'exposure_rating':rating,'automation_potential':SCORES[rating],'judgment_intensity':judgment,'exposure_category':category,'exposure_rationale':rationale,'family_label':families})
    return output
if __name__ == '__main__': print(write_repository())
